from h import *
R=[]
R.append((6662295,{
"ar":L("سمك الهلبوت على الطريقة التايلندية مع صلصة المانجو",
"يُلاحَظ في المطبخ التايلندي التوازن بين \"الحلاوة\" و\"الحرارة\"، وهذا الطبق ليس استثناءً. فـ\"الحرارة\" تأتي من الفلفل التايلندي الحار و\"الحلاوة\" من المانجو. ومعًا لا يقدمان هذا الثنائي المميز من الحلو والحار فحسب، بل أيضًا صلصة (ريليش) جميلة تشبه السالسا تسيل لها اللعاب لتُقدَّم مع السمك.",
"4","4 أونصات سمك + ⅓ كوب صلصة",
["1½ ملعقة كبيرة زيت بذور العنب (مقسّم)","3 ساق بصل أخضر (مقطع شرائح رفيعة، مع فصل الجزء الأخضر عن الأبيض)","1 حبة فلفل تايلندي حار صغيرة أو ½ حبة هالبينو صغيرة (مفرومة)","1 حبة مانجو كبيرة (صلبة وناضجة، مقشرة ومنزوعة النواة ومقطعة مكعبات بحجم ½ بوصة (2 كوب))","1 ملعقة صغيرة صلصة صويا (مخمّرة طبيعيًا، منخفضة الصوديوم)","1 ملعقة كبيرة عصير ½ ليمونة خضراء","4 شرائح سمك هلبوت (5 أونصات لكل شريحة، مجففة بالتربيت)","½ ملعقة صغيرة ملح بحري","¼ ملعقة صغيرة فلفل أسود (مطحون طازجًا)","1 ملعقة كبيرة كزبرة خضراء أو ريحان طازج (مفروم)"],
["سخّن ½ ملعقة كبيرة من الزيت في مقلاة متوسطة غير لاصقة على نار متوسطة. أضف الجزء الأبيض من البصل الأخضر وفلفل الشطة وقلّبهما حتى يبدأ البصل الأخضر بالتكرمل، لمدة 3½ دقائق تقريبًا. أضف المانجو وصلصة الصويا واطهه مع التحريك حتى تلين المانجو، لمدة 7 دقائق تقريبًا. أضف عصير الليمون الأخضر والجزء الأخضر من البصل الأخضر وقلّب، ثم انقله إلى وعاء وضعه جانبًا.",
"تبّل السمك بالملح والفلفل. سخّن 1 ملعقة كبيرة المتبقية من الزيت في مقلاة كبيرة غير لاصقة على نار متوسطة إلى عالية. أضف الشرائح وقلّبها حتى تنضج تمامًا وتصبح بنية فاتحة، لمدة 3 دقائق تقريبًا لكل جانب. (ملاحظة: حضّرها على دفعات إذا لزم الأمر.)",
"ضع صلصة المانجو فوق الشرائح ورشّ الكزبرة الخضراء وقدّمها."])}))
R.append((6664392,{
"es":L("Calabacitas con elote y pimientos",
"Esta guarnición es una manera perfecta de aprovechar todas las calabacitas y pimientos de su huerto de verano, o los que compre en el mercado de agricultores. Con solo un toque picante, este plato es fácil de preparar y combina muy bien con pescado o pollo a la parrilla.",
"8","1 taza",
["1/4 cucharadita de pimienta negra","1/2 cucharadita de sal","2 elotes enteros (sin hojas ni barbas, con los granos cortados de la mazorca (1 1/2 tazas de granos))","4 calabacitas medianas (en rodajas finas)","1/2 chile jalapeño entero (sin semillas y picado)","1 pimiento morrón rojo mediano (sin corazón ni semillas, en cubos)","2 dientes de ajo (picados)","1 cebolla mediana (picada)","1 1/2 cucharadas de aceite de oliva"],
["En un sartén grande, caliente el aceite a fuego medio. Agregue la cebolla y saltee por 5 minutos. Agregue el ajo y los pimientos rojo y jalapeño, y saltee por 2 minutos.",
"Agregue las calabacitas y saltee de 3 a 4 minutos. Agregue el elote al sartén y saltee de 2 a 4 minutos. Sazone con la sal y la pimienta negra."]),
"ar":L("كوسا مع الذرة والفلفل",
"هذا الطبق الجانبي طريقة مثالية لاستخدام كل ما لديك من كوسا وفلفل من حديقتك الصيفية أو من سوق المزارعين. وبلمسة حارة خفيفة، يسهل تحضير هذا الطبق ويناسب السمك أو الدجاج المشوي.",
"8","1 كوب",
["¼ ملعقة صغيرة فلفل أسود","½ ملعقة صغيرة ملح","2 كوز ذرة كامل (منزوع القشر والخيوط، مع فصل الحبوب عن الكوز (1½ كوب حبوب))","4 حبات كوسا متوسطة (مقطعة شرائح رفيعة)","½ حبة هالبينو كاملة (منزوعة البذور ومفرومة)","1 حبة فلفل رومي أحمر متوسطة (منزوعة القلب والبذور ومقطعة مكعبات)","2 فص ثوم (مفروم)","1 حبة بصل متوسطة (مقطعة)","1½ ملعقة كبيرة زيت زيتون"],
["في مقلاة كبيرة، سخّن الزيت على نار متوسطة. أضف البصل وقلّبه لمدة 5 دقائق. أضف الثوم والفلفل الأحمر والهالبينو وقلّبها لمدة دقيقتين.",
"أضف الكوسا وقلّبها لمدة 3 إلى 4 دقائق. أضف الذرة إلى المقلاة وقلّبها لمدة 2 إلى 4 دقائق. تبّل بالملح والفلفل الأسود."])}))
R.append((6664734,{
"es":L("Bocaditos de calabacita a la parrilla con salsa de tomate, aceitunas y piñones",
"Realce sus calabacitas a la parrilla con esta receta apta para personas con diabetes. Una salsa fresca de tomates, aceitunas y piñones aporta un toque sabroso a las calabacitas, bajas en carbohidratos.",
"8","1/2 taza",
["1 tomate roma mediano (en cubos)","1/4 taza de aceitunas Kalamata (sin hueso, picadas finamente)","3 cucharadas de piñones (tostados)","2 cucharadas de perejil fresco (picado)","3/4 cucharadita de sal kosher (dividida)","2 calabacitas medianas (cortadas en rodajas de 1/4 de pulgada de grosor)","1 cucharada de aceite de coco","1 diente de ajo (picado)"],
["En un tazón pequeño, mezcle el tomate, las aceitunas Kalamata, los piñones, el perejil y 1/4 cucharadita de sal kosher. Reserve.",
"Precaliente una plancha para asar o una parrilla a fuego medio-alto.",
"En un tazón, mezcle las rodajas de calabacita con el aceite de coco, el ajo picado y 1/4 cucharadita de sal kosher. Colóquelas en la parrilla y áselas por 3 minutos de cada lado.",
"Sirva cada rodaja tibia con una generosa cantidad de salsa por encima."]),
"ar":L("لقيمات الكوسا المشوية مع سالسا الطماطم والزيتون والصنوبر",
"ارتقِ بالكوسا المشوية مع هذه الوصفة المناسبة لمرضى السكري. فالسالسا الطازجة المصنوعة من الطماطم والزيتون والصنوبر تضيف نكهة لذيذة إلى الكوسا قليلة الكربوهيدرات.",
"8","½ كوب",
["1 حبة طماطم روما متوسطة (مقطعة مكعبات)","¼ كوب زيتون كالاماتا (منزوع النوى، مفروم ناعمًا)","3 ملاعق كبيرة صنوبر (محمص)","2 ملعقة كبيرة بقدونس طازج (مفروم)","¾ ملعقة صغيرة ملح كوشر (مقسّم)","2 حبة كوسا متوسطة (مقطعة شرائح بعرض ¼ بوصة)","1 ملعقة كبيرة زيت جوز الهند","1 فص ثوم (مفروم)"],
["في وعاء صغير، اخلط الطماطم وزيتون كالاماتا والصنوبر والبقدونس و¼ ملعقة صغيرة من ملح الكوشر. ضعه جانبًا.",
"سخّن مقلاة شواء أو شواية على نار متوسطة إلى عالية.",
"في وعاء، قلّب شرائح الكوسا مع زيت جوز الهند والثوم المفروم و¼ ملعقة صغيرة من ملح الكوشر. ضعها على الشواية واشوِها 3 دقائق على كل جانب.",
"قدّم كل شريحة دافئة مع كمية سخية من السالسا فوقها."])}))
R.append((6664964,{
"es":L("Berenjena griega asada con queso feta",
"Las guarniciones no deben considerarse un complemento menor. Merecen tanto cariño y atención culinaria como los platos principales. Si busca una guarnición que impresione, esta receta de berenjena asada es la indicada. Los toques finales de hierbas frescas, queso feta y ralladura de limón hacen que esta guarnición sea casi la estrella del plato.",
"4","2 cuñas",
["3 cucharadas de salsa marinara","1 cucharada de jugo de limón","1 cucharada de aceite de oliva extra virgen","1 diente de ajo (picado)","1/4 cucharadita de sal de mar","1/4 cucharadita de canela molida","2 berenjenas medianas (cada una cortada en cuartos a lo largo, sin los tallos)","3 cucharadas de perejil fresco","1 cucharada de menta fresca (picada, O 1 cucharadita de orégano fresco picado)","3 cucharadas de queso feta (desmenuzado finamente)","1/2 cucharada de ralladura de limón"],
["Precaliente el horno a 400 °F. En un tazón pequeño, bata la salsa marinara, el jugo de limón, el aceite, el ajo, la sal y la canela. Acomode las cuñas de berenjena, con la piel hacia abajo, en una bandeja para hornear cubierta con papel pergamino sin blanquear. Pincele generosamente las superficies cortadas de las cuñas de berenjena con la mezcla de marinara.",
"Ase las cuñas de berenjena hasta que estén completamente cocidas, aproximadamente 30 minutos.",
"Pase a una fuente, espolvoree con el perejil, la menta, el queso feta y la ralladura de limón, y sirva."]),
"ar":L("باذنجان يوناني محمّص مع جبن الفيتا",
"لا ينبغي اعتبار الأطباق الجانبية مجرد أمر ثانوي، فهي تستحق من العناية والاهتمام في الطهي قدر ما تستحقه الأطباق الرئيسية. وإذا كنت تبحث عن طبق جانبي يترك انطباعًا رائعًا، فوصفة الباذنجان المحمّص هذه هي المناسبة. فلمسات التزيين الأخيرة من الأعشاب الطازجة وجبن الفيتا وقشر الليمون المبشور تجعل هذا الطبق الجانبي أقرب إلى نجم الطبق.",
"4","شريحتان",
["3 ملاعق كبيرة صلصة مارينارا","1 ملعقة كبيرة عصير ليمون","1 ملعقة كبيرة زيت زيتون بكر ممتاز","1 فص ثوم (مفروم)","¼ ملعقة صغيرة ملح بحري","¼ ملعقة صغيرة قرفة مطحونة","2 حبة باذنجان متوسطة (تُقطَّع كل واحدة إلى أربعة أجزاء طوليًا، مع إزالة السيقان)","3 ملاعق كبيرة بقدونس طازج","1 ملعقة كبيرة نعناع طازج (مفروم، أو 1 ملعقة صغيرة أوريجانو طازج مفروم)","3 ملاعق كبيرة جبن فيتا (مفتت ناعمًا)","½ ملعقة كبيرة قشر ليمون مبشور"],
["سخّن الفرن مسبقًا إلى 400° فهرنهايت (200° مئوية). في وعاء صغير، اخفق صلصة المارينارا وعصير الليمون والزيت والثوم والملح والقرفة. رتّب شرائح الباذنجان وجهة القشرة إلى الأسفل على صينية خبز مبطنة بورق زبدة غير مبيّض. ادهن أسطح القطع من شرائح الباذنجان بسخاء بخليط المارينارا.",
"حمّص شرائح الباذنجان حتى تنضج تمامًا، لمدة 30 دقيقة تقريبًا.",
"انقلها إلى طبق تقديم، ورشّ فوقها البقدونس والنعناع وجبن الفيتا وقشر الليمون المبشور، وقدّمها."])}))
R.append((6665438,{
"ar":L("غموس السبانخ والخرشوف",
"هذه المقبلات قليلة الكربوهيدرات نسخة أخف بكثير من غموس السبانخ والخرشوف التقليدي، لكنها تحتفظ بنكهة رائعة. حضّر هذا الغموس في وقت قصير لحفلتك القادمة.",
"12","2 ملعقة كبيرة",
["1½ كوب قلوب خرشوف مجمدة (مفرومة ومذابة)","1 كوب سبانخ مجمدة (مفرومة، مذابة)","5 (شرائح مثلثة) جبن خفيف بالثوم والأعشاب","1 ملعقة كبيرة عصير ليمون (من ½ ليمونة متوسطة)","2 ملعقة كبيرة مايونيز خفيف","3 ملاعق كبيرة جبن بارميزان (مبشور)","¼ ملعقة صغيرة رقائق الفلفل الأحمر المطحون"],
["في قدر صغير، اغلِ السبانخ والخرشوف في 1 كوب ماء حتى يلينا. تخلّص من السائل وصفِّهما جيدًا وضع الخرشوف والسبانخ جانبًا في وعاء.",
"في القدر نفسه، ذوّب شرائح جبن Laughing Cow على نار هادئة. أضف المكونات المتبقية؛ واخلطها جيدًا وواصل الطهي لمدة 1-2 دقيقة إضافية.",
"أضف السبانخ والخرشوف المصفّيين إلى القدر وقلّب. اطهها دقيقتين إضافيتين.",
"قدّمه دافئًا مع الخضار التي تختارها أو مع مقرمشات القمح الكامل."])}))
R.append((6665652,{
"ar":L("سبانخ سوتيه بالثوم",
"قدّم هذه السبانخ السوتيه بالثوم مع وصفة السلمون بالديجون لوجبة فاخرة. ويُعد الثوم المحمّص مقبلات رائعة أيضًا؛ فقط قدّم فصوص الثوم المحمّصة مع كروستيني القمح الكامل واترك ضيوفك يفردون الثوم على الخبز المحمص.",
"4","½ كوب",
["1 رأس ثوم","1 ملعقة كبيرة زيت زيتون (مقسّم)","1 بخّة، 0.25 غرام بخاخ طهي غير لاصق","½ كوب بصل (مفروم ناعمًا)","6 كوب سبانخ","½ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود"],
["سخّن الفرن مسبقًا إلى 400° فهرنهايت (200° مئوية).",
"مع إبقاء رأس الثوم كاملًا، اقطع من ¼ إلى ½ بوصة من أعلى الرأس لتكشف فصوص الثوم المنفصلة. أبقِ القشرة عليها.",
"ضع رأس الثوم وجهة القطع إلى الأعلى على قطعة من ورق الألومنيوم. رُشّ 1 ملعقة صغيرة من زيت الزيتون على سطح القطع من رأس الثوم. اطوِ الورق حول الثوم واضغط لإحكام الإغلاق لتكوين كيس.",
"اخبزه على 400° فهرنهايت (200° مئوية) لمدة 30-35 دقيقة، أو حتى تصبح الفصوص طرية عند الضغط عليها.",
"اترك الثوم ليبرد قليلًا حتى يمكن لمسه. اعصر فصوص الثوم المحمّصة من قشورها في وعاء صغير واهرسها بالشوكة لتحصل على معجون.",
"في مقلاة سوتيه كبيرة، أضف زيت الزيتون المتبقي وكمية سخية من بخاخ الطهي على نار متوسطة إلى عالية. أضف البصل وقلّبه حتى يبدأ بالتكرمل فقط.",
"أضف معجون الثوم المحمّص وقلّب حتى يتغطى البصل. أضف السبانخ وقلّبها حتى تذبل وتتغطى بالثوم والبصل.",
"تبّل بالملح والفلفل."])}))
R.append((6665803,{
"es":L("Tostada fácil de ensalada de pollo",
"Esta ensalada de pollo fácil es una excelente manera de aprovechar el pollo cocido que le sobró. También puede usar pollo o atún enlatado. Agregue algunas hojas verdes, como espinacas, lechuga o rúcula, a su sándwich abierto para sumar más verduras. Como opción baja en carbohidratos, sírvala en un wrap de lechuga en lugar de sobre tostada.",
"4","1 sándwich abierto",
["2 tazas de pollo cocido (deshebrado o en cubos)","1/4 taza de mayonesa light","1/4 taza de yogur griego natural sin grasa","2 cucharadas de cebolla picada finamente","1/4 cucharadita de sal","1/4 cucharadita de pimienta negra","1 cucharadita de eneldo seco","4 rebanadas de pan integral (tostado)","1/4 taza de almendras en tiras"],
["En un tazón, mezcle el pollo, la mayonesa light, el yogur griego, la cebolla picada, la sal, la pimienta negra y el eneldo seco.",
"Cubra una tostada con 1/2 taza de la mezcla de ensalada de pollo. Cubra con 1 cucharada de almendras en tiras tostadas.",
"Repita con las otras 3 tostadas, o guarde la ensalada de pollo separada de las nueces en un recipiente hermético en el refrigerador hasta por 1 semana y arme los sándwiches abiertos según los necesite."]),
"ar":L("توست سلطة الدجاج السهلة",
"سلطة الدجاج السهلة هذه طريقة رائعة لإعادة استخدام الدجاج المطبوخ المتبقي. يمكنك أيضًا استخدام الدجاج المعلب أو التونة بدلًا منه. أضف بعض الخضار الورقية مثل السبانخ أو الخس أو الجرجير إلى ساندويتشك المفتوح لزيادة الخضار. وللحصول على خيار قليل الكربوهيدرات، قدّمها ملفوفة في أوراق الخس بدلًا من التوست.",
"4","1 ساندويتش مفتوح",
["2 كوب دجاج مطبوخ (مفتت أو مقطع مكعبات)","¼ كوب مايونيز خفيف","¼ كوب زبادي يوناني سادة خالٍ من الدسم","2 ملعقة كبيرة بصل مفروم ناعمًا","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","1 ملعقة صغيرة شبت مجفف","4 شرائح خبز قمح كامل (محمصة)","¼ كوب لوز شرائح رفيعة"],
["في وعاء، اخلط الدجاج والمايونيز الخفيف والزبادي اليوناني والبصل المفروم والملح والفلفل الأسود والشبت المجفف.",
"ضع ½ كوب من خليط سلطة الدجاج فوق قطعة توست واحدة. ضع فوقها 1 ملعقة كبيرة من اللوز الشرائح المحمّص.",
"كرّر ذلك مع قطع التوست الـ 3 المتبقية، أو احفظ سلطة الدجاج منفصلة عن المكسرات في وعاء محكم الإغلاق في الثلاجة حتى 1 أسبوع، وحضّر الساندويتشات المفتوحة عند الحاجة."])}))
R.append((6666824,{
"es":L("Pollo coreano picante con ensalada crujiente de pepino",
"Esta receta baja en carbohidratos y baja en grasa presenta un plato de pollo picante de inspiración coreana, con el intenso picor del gochujang —una pasta de chile rojo fermentada, rica, sabrosa y ligeramente dulce— equilibrado con una ensalada de pepino fresca y crujiente. El uso de pechuga de pollo magra y una marinada ligeramente endulzada mantiene la comida llena de sabor sin exceso de azúcar ni de grasa. Es una excelente opción para personas con diabetes que desean disfrutar de sabores vibrantes cuidando su nivel de glucosa en la sangre (azúcar en la sangre).",
"4","3 oz de pollo + 1/2 taza de ensalada de pepino",
["12 onzas de pechugas de pollo deshuesadas y sin piel (cortadas en tiras)","5 cebollitas de cambray enteras (en rodajas)","2 dientes de ajo (picados en trozos grandes)","1 cucharada de salsa de soya reducida en sodio","1/3 taza de salsa sriracha o gochujang","1 1/2 cucharaditas de mezcla alternativa de azúcar morena","1 cucharada de aceite de sésamo","2 cucharadas de vinagre de vino de arroz","1 pepino inglés entero (en rodajas finas)","1 chile rojo largo entero (sin semillas y picado finamente)","1/4 taza de cilantro fresco (picado en trozos grandes)","1 cucharada de semillas de ajonjolí"],
["En una licuadora o procesador de alimentos, combine tres cebollitas de cambray picadas en trozos grandes, el ajo, la salsa de soya, el gochujang, la alternativa de azúcar morena, el aceite de sésamo y el vinagre de vino de arroz. Licúe hasta que quede suave.",
"Coloque las tiras de pollo en una bolsa de plástico grande con cierre hermético o en un recipiente poco profundo. Vierta la marinada sobre el pollo, reservando 2 cucharadas para servir. Selle la bolsa o cubra el recipiente y refrigere por al menos 20 minutos para marinar.",
"En un tazón mediano, combine los pepinos en rodajas, el chile rojo picado, la cebollita de cambray en rodajas y el cilantro.",
"En un tazón pequeño, bata el vinagre de vino de arroz y 1/2 cucharadita de la alternativa de azúcar morena hasta que el azúcar se disuelva. Vierta este aderezo sobre la mezcla de pepino y mezcle para cubrir. Reserve.",
"Precaliente a fuego medio una plancha para asar o un sartén ligeramente engrasado.",
"Saque el pollo de la marinada, dejando que escurra el exceso. Coloque el pollo en la plancha y cocínelo de 6 a 8 minutos, volteándolo de vez en cuando, hasta que esté bien cocido y tenga un ligero chamuscado.",
"Rocíe con la marinada reservada y espolvoree con 1 cucharada de semillas de ajonjolí tostadas y dos cebollitas de cambray en rodajas."]),
"ar":L("دجاج كوري حار مع سلطة الخيار المقرمشة",
"هذه وصفة قليلة الكربوهيدرات وقليلة الدسم تقدم طبق دجاج حارًا مستوحى من المطبخ الكوري، وتمنحك حرارة قوية من الغوتشوجانغ (معجون فلفل أحمر مخمّر غني ولذيذ وحلو قليلًا) وتوازنه بسلطة خيار باردة ومقرمشة. استخدام صدور الدجاج الخالية من الدهن وتتبيلة محلاة قليلًا يُبقي الوجبة غنية بالنكهة دون الإفراط في السكر أو الدهون. إنه خيار رائع لمرضى السكري الذين يرغبون في الاستمتاع بنكهات نابضة بالحياة مع مراعاة مستوى الجلوكوز في الدم (سكر الدم).",
"4","3 أونصات دجاج + ½ كوب سلطة خيار",
["12 أونصة صدور دجاج منزوعة العظم والجلد (مقطعة إلى شرائح طولية)","5 حبات بصل أخضر كاملة (مقطعة شرائح)","2 فص ثوم (مفروم تقطيعًا خشنًا)","1 ملعقة كبيرة صلصة صويا منخفضة الصوديوم","⅓ كوب صلصة سريراتشا أو غوتشوجانغ","1½ ملعقة صغيرة خليط بديل السكر البني","1 ملعقة كبيرة زيت السمسم","2 ملعقة كبيرة خل أرز","1 حبة خيار إنجليزي كاملة (مقطعة شرائح رفيعة)","1 حبة فلفل أحمر حار طويل كاملة (منزوعة البذور ومفرومة ناعمًا)","¼ كوب كزبرة خضراء طازجة (مفرومة تقطيعًا خشنًا)","1 ملعقة كبيرة بذور سمسم"],
["في خلاط أو محضّرة طعام، اخلط ثلاث حبات بصل أخضر مقطعة تقطيعًا خشنًا والثوم وصلصة الصويا والغوتشوجانغ وبديل السكر البني وزيت السمسم وخل الأرز. اخلطها حتى تصبح ناعمة.",
"ضع شرائح الدجاج في كيس بلاستيكي كبير قابل للإغلاق أو في طبق عريض. اسكب التتبيلة فوق الدجاج مع الاحتفاظ بملعقتين كبيرتين للتقديم. أغلق الكيس أو غطِّ الطبق وضعه في الثلاجة لمدة 20 دقيقة على الأقل ليتتبّل.",
"في وعاء متوسط، اخلط الخيار المقطع شرائح والفلفل الأحمر المفروم والبصل الأخضر المقطع شرائح والكزبرة الخضراء.",
"في وعاء صغير، اخفق خل الأرز و½ ملعقة صغيرة من بديل السكر البني حتى يذوب السكر. اسكب هذه الصلصة فوق خليط الخيار وقلّب ليتغطى. ضعه جانبًا.",
"سخّن مقلاة شواء أو مقلاة مدهونة قليلًا بالزيت على نار متوسطة.",
"أخرج الدجاج من التتبيلة واترك الفائض ينزّ منه. ضع الدجاج على المقلاة واطهه لمدة 6-8 دقائق مع تقليبه من حين لآخر، حتى ينضج تمامًا ويكتسب تفحمًا خفيفًا.",
"رُشّ عليه التتبيلة المحتفظ بها، وانثر 1 ملعقة كبيرة من بذور السمسم المحمّصة وحبتين من البصل الأخضر المقطع شرائح."])}))
R.append((6666899,{
"es":L("Ensalada de manzana, betabel y zanahoria con vinagreta de naranja sanguina",
"\"Descubrí\" esta deliciosa ensalada mientras hacía trabajo voluntario en una escuela primaria de Washington, D.C., donde los niños decían que su comida favorita era la \"ensalada ABC\", ¡que preparaban con ingredientes del huerto escolar! Fue tan inspirador ver a los niños devorar las verduras con tanto gusto que yo también me hice fan. ¡Incluso empecé a incluirla en mis clases de cocina \"Culinary Medicine Made Easy\" y en tantos menús como fue posible!",
"4","1 taza",
["1 betabel mediano (fresco, pelado y rallado)","2 zanahorias medianas (peladas y ralladas)","1 manzana grande Granny Smith u otra manzana ácida (pelada y rallada)","1/4 taza de nueces (picadas)","3 cucharadas de perejil fresco, eneldo o una combinación de ambos (picado)","1/4 taza de jugo de 1 naranja sanguina","1/4 cucharadita de sal","1/4 cucharadita de pimienta negra","2 cucharadas de aceite de oliva"],
["Coloque el betabel, las zanahorias y la manzana ralladas en un tazón grande y mezcle para combinar. Agregue las nueces y las hierbas verdes encima de la mezcla y reserve el tazón.",
"En un tazón pequeño, bata el jugo de naranja sanguina con la sal hasta que la sal se disuelva. Agregue 3 o 4 vueltas de pimienta del molino y luego incorpore el aceite batiendo. Vierta el aderezo sobre la ensalada y mezcle hasta que esté bien combinada y uniformemente aderezada. Sirva la ensalada dentro de 1 hora después de combinarla con las hierbas y el aderezo."]),
"ar":L("سلطة التفاح والشمندر والجزر مع صلصة برتقال الدم",
"\"اكتشفت\" هذه السلطة اللذيذة أثناء عملي التطوعي في مدرسة ابتدائية في واشنطن العاصمة، حيث قال الأطفال إن طعامهم المفضل هو \"سلطة ABC\"، التي كانوا يحضّرونها من مكونات حديقة المدرسة! كان من الملهم جدًا أن أرى الأطفال يلتهمون الخضار بمثل هذه المتعة حتى أصبحت من المعجبين بها أنا أيضًا! بل بدأت أدرجها في دروس الطبخ التي أقدمها بعنوان \"Culinary Medicine Made Easy\" وفي أكبر عدد ممكن من قوائم الطعام.",
"4","1 كوب",
["1 حبة شمندر متوسطة (طازجة، مقشرة ومبشورة)","2 حبة جزر متوسطة (مقشرة ومبشورة)","1 حبة تفاح كبيرة غراني سميث أو أي تفاح حامض آخر (مقشرة ومبشورة)","¼ كوب جوز (مفروم)","3 ملاعق كبيرة بقدونس طازج أو شبت أو مزيج منهما (مفروم)","¼ كوب عصير 1 برتقالة دم","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","2 ملعقة كبيرة زيت زيتون"],
["ضع الشمندر والجزر والتفاح المبشور في وعاء خلط واخلطها معًا. أضف الجوز والأعشاب الخضراء فوق الخليط وضع الوعاء جانبًا.",
"في وعاء صغير، اخفق عصير برتقال الدم مع الملح حتى يذوب الملح. أضف 3–4 طحنات من الفلفل ثم اخفق معها الزيت. اسكب الصلصة فوق السلطة وقلّب حتى تمتزج جيدًا وتتغطى بالتساوي. قدّم السلطة خلال 1 ساعة من خلطها بالأعشاب والصلصة."])}))
R.append((6667936,{
"es":L("Batido verde energético",
"¡Súmese a lo verde con este delicioso y nutritivo batido! Repleto de verduras sin almidón, es una receta apta para personas con diabetes y con menos carbohidratos que la mayoría de los demás batidos.",
"1","12 oz",
["1 taza de espinacas tiernas","1/2 aguacate mediano","1/2 taza de pepino (picado en trozos grandes)","1/2 taza de leche de almendra sin azúcar","1/2 taza de hielo"],
["Agregue las espinacas, el aguacate, el pepino, la leche de almendra y el hielo a una licuadora. Licúe hasta que quede suave y cremoso.",
"Vierta en un vaso alto y disfrute de inmediato."]),
"ar":L("سموذي الطاقة الخضراء",
"أضف اللون الأخضر إلى يومك مع هذا السموذي اللذيذ والمغذي! وهو مليء بالخضار غير النشوية، وهو وصفة مناسبة لمرضى السكري وأقل في الكربوهيدرات من معظم أنواع السموذي الأخرى.",
"1","12 أونصة",
["1 كوب سبانخ صغيرة","½ حبة أفوكادو متوسطة","½ كوب خيار (مقطع تقطيعًا خشنًا)","½ كوب حليب اللوز غير المحلى","½ كوب ثلج"],
["ضع السبانخ والأفوكادو والخيار وحليب اللوز والثلج في خلاط. اخلطها حتى تصبح ناعمة وكريمية.",
"اسكبه في كوب طويل واستمتع به فورًا."])}))
R.append((6669746,{
"ar":L("فاصولياء خضراء محمّصة بصلصة الشمبانيا",
"أبهر ضيوفك بتحضير هذا الطبق الجانبي البسيط والأنيق ليرافق أي طبق رئيسي من الدجاج أو السمك أو اللحم البقري. هذا الطبق الجانبي من الخضار مثالي ليُقدَّم مع وجبة فاخرة من المأكولات البحرية واللحوم.",
"6","¾ كوب",
["1 بخّة، 0.25 غرام بخاخ طهي غير لاصق","1½ رطل فاصولياء خضراء طازجة (مقصوصة الأطراف)","1 ملعقة كبيرة زائد 1 ملعقة صغيرة زيت زيتون (مقسّم)","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","1 ملعقة كبيرة ثوم (مفروم)","2 ملعقة كبيرة خل الشمبانيا","1 ملعقة صغيرة خردل ديجون","1 ملعقة صغيرة بديل السكر","¼ ملعقة صغيرة رقائق الفلفل الأحمر المطحون"],
["سخّن الفرن مسبقًا إلى 400 درجة فهرنهايت (200 درجة مئوية). رُشّ صينية الخبز ببخاخ الطهي. ضعها جانبًا.",
"في وعاء كبير، قلّب الفاصولياء الخضراء مع 1 ملعقة صغيرة من زيت الزيتون والملح والفلفل والثوم. اسكبها على صينية الخبز المجهّزة وحمّصها لمدة 25 دقيقة أو حتى تنضج وتبدأ بالتحمير.",
"بينما تنضج الفاصولياء الخضراء، اخفق 1 ملعقة كبيرة من زيت الزيتون وخل الشمبانيا وخردل ديجون وبديل السكر ورقائق الفلفل الأحمر المطحون. ضعه جانبًا.",
"عند انتهاء تحميص الفاصولياء الخضراء، رُشّ عليها صلصة الشمبانيا وقلّبها لتتغطى."])}))
R.append((6670382,{
"es":L("Pechuga de pollo cocida, 4 onzas","Información nutricional de la pechuga de pollo cocida.","1","4 onzas",["4 onzas de pechuga de pollo (sin piel, cocida)"],[]),
"ar":L("صدر دجاج مطبوخ، 4 أونصات","المعلومات الغذائية لصدر الدجاج المطبوخ.","1","4 أونصات",["4 أونصات صدر دجاج (بدون جلد، مطبوخ)"],[])}))
R.append((6671502,{
"ar":L("أكياس التونة المشوية بالتيرياكي",
"الشواء في أكياس من ورق الألومنيوم يتيح لجميع النكهات أن تمتزج، كما أن التنظيف بعده سهل للغاية! وإذا لم تكن لديك شواية، فيمكنك خبزها في الفرن. سخّنه إلى 375° فهرنهايت (190° مئوية) واخبزها لمدة 20 دقيقة.",
"4","4 أونصات تونة + ½ كوب خضار",
["2½ ملعقة كبيرة صلصة صويا منخفضة الصوديوم","2½ ملعقة كبيرة ماء","1 ملعقة كبيرة عسل","1 ملعقة كبيرة زنجبيل طازج (مفروم)","2 فص ثوم (مفروم)","2 ملعقة صغيرة زيت سمسم محمص","4 قطع ورق ألومنيوم (طول كل منها 12 بوصة)","1 بخّة، 0.25 غرام بخاخ طهي غير لاصق","12 أونصة خليط خضار للقلي بالتحريك، طازج أو مجمد","1 ملعقة صغيرة بهارات (بدون ملح، (مثل Mrs. Dash أو Salt-Free Spike))","1 رطل شريحة تونة ياقوتية الزعانف (أهي) (تُقسَّم إلى 4 حصص، 4 أونصات لكل حصة، طازجة أو مجمدة؛ وإذا كانت مجمدة فاتركها لتذوب قبل الاستخدام)"],
["في قدر صغير، اخفق صلصة الصويا والماء والعسل والزنجبيل وزيت السمسم والثوم. اتركها حتى تغلي، ثم خفّف النار إلى غليان هادئ. دعها تغلي بهدوء لمدة 7 إلى 8 دقائق أو حتى تتركّز الصلصة وتصبح شبه شرابية. ضعها جانبًا لتبرد.",
"سخّن شواية خارجية على حرارة متوسطة ورشّ أحد وجهي كل قطعة من ورق الألومنيوم ببخاخ الطهي.",
"في وعاء متوسط، قلّب الخضار والثوم والبهارات معًا.",
"وزّع الخضار بالتساوي على قطع ورق الألومنيوم. ضع فوق الخضار قطعة من شريحة التونة ورُشّ 1 ملعقة كبيرة من صلصة التيرياكي المحضّرة فوق التونة.",
"قرّب أطراف ورق الألومنيوم من بعضها واطوِها بإحكام ثلاث مرات حتى تُغلق لتكوين كيس.",
"اشوِ الأكياس لمدة 20 دقيقة. كن حذرًا عند فتح الأكياس؛ فقد يكون البخار ساخنًا."])}))
save("out_c18_part3.json",R)
